excels.excel:

EXPORT WITH SHEET="客户拜访记录台账", HEADER=true,
    MAPPING={"a":"拜访日期","b":"客户名称","c":"拜访人","d":"拜访方式","e":"拜访时长(h)","f":"客户等级","g":"跟进状态"},
    FORMAT={"a":"yyyy-MM-dd","e":"#,##0.0"},
    FORMULAS={
        E8:'SUM(E2:E7)'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        G5:{color:red,bold:true},
        G7:{color:red,bold:true}
    }
